INSERT INTO author (id, bio, category, created_at) VALUES
  ('0b3adb2f-ede5-544d-83c1-9810168d00f1', 'Иллюстратор и скетчер. Рисую городские зарисовки, делюсь процессом, ошибками и разборами работ.', 'Искусство', '2026-09-01 12:30:00+03'),
  ('6b030622-ac23-5cab-8db2-707c04a38fe8', 'Backend-разработчик на Go. Пишу про базы данных, транзакции и архитектуру сервисов без воды.', 'Программирование', '2026-09-02 12:30:00+03'),
  ('2b24348d-73d4-503d-8b54-5820b4da94b2', 'Путешествую по северу России с рюкзаком и камерой. Маршруты, бюджеты и честные впечатления.', 'Путешествия', '2026-09-03 12:30:00+03'),
  ('23497e59-94d8-59b5-ba9b-f4a0ddd3c880', 'Гитарист и автор песен. Объясняю теорию простыми словами и показываю, как записывать музыку дома.', 'Музыка', '2026-09-04 12:30:00+03');
INSERT INTO subscription_type (id, author_id, name, description, level, created_at) VALUES
  ('6a394c25-9dfe-51f6-abab-a59eae31b724', '0b3adb2f-ede5-544d-83c1-9810168d00f1', 'Друг студии', 'Доступ к разборам палитры и видеоурокам по скетчингу.', 1, '2026-09-20 10:00:00+03'),
  ('8e21101c-6c49-5fd9-b9ea-70f1df168b1d', '6b030622-ac23-5cab-8db2-707c04a38fe8', 'Сторонник', 'Закрытые разборы кода и материалы с практикой на Go и PostgreSQL.', 1, '2026-09-20 10:00:00+03');
INSERT INTO post (id, author_id, title, body, status, published_at, created_at, updated_at) VALUES
  ('a8ed24b9-2a50-529e-8db1-aeb94a2a2a06', '0b3adb2f-ede5-544d-83c1-9810168d00f1', 'Как я начала вести скетчбук: первые 30 дней', 'Месяц назад я решила рисовать каждый день хотя бы по десять минут. Правило одно: никаких «плохих» страниц, любая страница считается.
